import json, glob, os
dirs = ['/root/colliforce-vla/eval_results/', '/root/autodl-tmp/eval_results/', '/root/colliforce-vla/']
for d in dirs:
    if not os.path.isdir(d):
        print(f'{d}: NOT FOUND')
        continue
    files = glob.glob(os.path.join(d, '*eval*.json')) + glob.glob(os.path.join(d, '*result*.json'))
    if not files:
        continue
    print(f'=== {d} ({len(files)} json files) ===')
    for f in sorted(files):
        sz = os.path.getsize(f)
        from datetime import datetime
        mt = datetime.fromtimestamp(os.path.getmtime(f)).strftime('%Y-%m-%d %H:%M')
        print(f'  {os.path.basename(f)} ({sz}B, {mt})')
        try:
            data = json.load(open(f))
            keys = list(data.keys())[:15]
            print(f'    keys: {keys}')
            if 'episodes' in data:
                ep = data['episodes']
                if isinstance(ep, list) and len(ep) > 0:
                    print(f'    episodes[0]: {list(ep[0].keys())[:15]}')
                    has_disp = any('disp' in str(k).lower() for k in ep[0].keys())
                    print(f'    n_episodes={len(ep)}, has_displacement={has_disp}')
            for k in ['per_episode', 'episode_results', 'displacement', 'max_displacement']:
                if k in data:
                    v = data[k]
                    print(f'    {k}: type={type(v).__name__}, len={len(v) if hasattr(v,\"__len__\") else \"N/A\"}')
        except Exception as e:
            print(f'    ERROR: {e}')
